-- Restore for migration 20261101000000_approved_content_sync: puts back the production values of 2026-11-01.
-- Each row is reverted only if it still holds the value the migration wrote; the imported online catalog is removed.
-- Run once against the production database, for example on ilmora-admin:
--   docker compose exec -T postgres psql -U <user> -d <db> -v ON_ERROR_STOP=1 < 20261101_restore.sql
-- or ship it as a new migration. It never touches users, subscriptions, payments, enrollments or groups.

DO $sync$
DECLARE
  t text;
  n integer;
  applied integer := 0;
  skipped integer := 0;
  failed integer := 0;
BEGIN
  SELECT "tenantId" INTO t FROM "Course" WHERE "id" = 'c-general-english' AND "deletedAt" IS NULL;
  IF t IS NULL THEN
    RAISE NOTICE 'content sync: no ILMORA catalog in this database, nothing to do';
    RETURN;
  END IF;

  -- site settings: brand, nav, pages, faq, announcements
  BEGIN
    INSERT INTO "AuditEvent" ("id", "tenantId", "action", "entityType", "entityId", "before", "after", "reason")
    SELECT 'content-sync-20261101-restore-SiteConfig', t, 'content.sync.restore', 'SiteConfig', t, jsonb_build_object('version', "version", 'brand', "data"->'brand', 'nav', "data"->'nav', 'pages', "data"->'pages', 'faq', "data"->'faq', 'announcements', "data"->'announcements'), '{"announcements":[{"audience":"all","body":{"en":"Seats in new Bazis and Frontend groups are limited (demo announcement).","ru":"Места в новых группах Bazis и Frontend ограничены (демо-объявление).","uz":"Bazis va Frontend kurslarida yangi guruhlar uchun o‘rinlar cheklangan (demo e’lon)."},"enabled":true,"id":"a1","title":{"en":"October groups are open","ru":"Открыты группы на октябрь","uz":"Oktyabr guruhlari ochildi"}},{"audience":"teachers","body":{"en":"Remember to select an audience for private materials.","ru":"Не забывайте выбирать аудиторию для приватных материалов.","uz":"Yopiq materiallar uchun auditoriya tanlashni unutmang."},"enabled":true,"id":"a2","title":{"en":"For teachers: visibility settings","ru":"Для преподавателей: настройки видимости","uz":"O‘qituvchilar uchun: ko‘rinish sozlamalari"}}],"brand":{"city":{"en":"Tashkent, Uzbekistan","ru":"Ташкент, Узбекистан","uz":"Toshkent, O‘zbekiston"},"footerNote":{"en":"ILMORA is a sample education platform for education centers in Tashkent. This is a demo prototype: all centers, teachers, prices and materials are fictional.","ru":"ILMORA — демонстрационная образовательная платформа для учебных центров Ташкента. Это демо-прототип: все центры, преподаватели, цены и материалы вымышлены.","uz":"ILMORA — Toshkentdagi o‘quv markazlari uchun namuna ta’lim platformasi. Bu demo prototip: barcha markazlar, o‘qituvchilar, narxlar va materiallar xayoliy."},"heroHeadline":{"en":"Different education centers. One subscription.","ru":"Разные учебные центры. Один абонемент.","uz":"Turli o‘quv markazlari. Bitta abonement."},"heroTagline":{"en":"One subscription. Many possibilities.","ru":"Один абонемент. Множество возможностей.","uz":"Bir abonement. Bir nechta imkoniyat."},"name":"ILMORA","primaryCta":{"en":"Choose courses","ru":"Выбрать курсы","uz":"Kurslarni tanlash"}},"faq":[{"a":{"en":"The monthly total is the sum of selected course prices. The package (Duo/Trio) only sets how many courses you take at once.","ru":"Месячная сумма — сумма цен выбранных курсов. Пакет (Duo/Trio) лишь определяет число одновременных курсов.","uz":"Oylik summa — tanlangan kurslar narxlarining yig‘indisi. Paket (Duo/Trio) faqat bir vaqtdagi kurslar sonini belgilaydi."},"id":"f1","q":{"en":"How is the subscription price calculated?","ru":"Как рассчитывается цена абонемента?","uz":"Abonement narxi qanday hisoblanadi?"}},{"a":{"en":"No. Each course may appear once in a subscription; duplicates are blocked.","ru":"Нет. Каждый курс может быть в абонементе один раз; дубликаты блокируются.","uz":"Yo‘q. Har bir kurs abonementda bir marta bo‘lishi mumkin; takroriy tanlov bloklanadi."},"id":"f2","q":{"en":"Can I select the same course twice?","ru":"Можно ли выбрать один курс дважды?","uz":"Bir kursni ikki marta tanlash mumkinmi?"}},{"a":{"en":"The builder flags the conflict immediately and blocks activation. Choose another group.","ru":"Конструктор сразу показывает конфликт и не позволяет активировать. Выберите другую группу.","uz":"Abonement yig‘uvchi to‘qnashuvni darhol ko‘rsatadi va faollashtirishga ruxsat bermaydi. Boshqa guruhni tanlang."},"id":"f3","q":{"en":"What if schedules overlap?","ru":"Что если расписания пересекаются?","uz":"Jadval to‘qnashsa nima bo‘ladi?"}},{"a":{"en":"Yes. When you renew, you continue in the same groups.","ru":"Да. При продлении вы продолжаете обучение в тех же группах.","uz":"Ha. Yangilaganda siz o‘sha guruhlarda o‘qishni davom ettirasiz."},"id":"f4","q":{"en":"Do I keep my group when I renew?","ru":"Сохраняется ли моя группа при продлении?","uz":"Yangilaganda guruhim saqlanib qoladimi?"}},{"a":{"en":"No. Visibility and enrollment are separate: a public page or video doesn’t grant a seat in a paid group.","ru":"Нет. Видимость и зачисление разделены: публичная страница или видео не даёт места в платной группе.","uz":"Yo‘q. Ko‘rinish va ro‘yxatdan o‘tish alohida: ommaviy sahifa yoki video pullik guruhda o‘rin bermaydi."},"id":"f5","q":{"en":"Does a public video give free course access?","ru":"Даёт ли публичное видео бесплатный доступ к курсу?","uz":"Ommaviy video kursga bepul kirish beradimi?"}},{"a":{"en":"Only the teacher, authorized Super Admin, and the students or groups the teacher selected.","ru":"Только преподаватель, уполномоченный Супер-админ и выбранные преподавателем студенты или группы.","uz":"Faqat o‘qituvchi, vakolatli Super Admin va o‘qituvchi tanlagan talabalar yoki guruhlar."},"id":"f6","q":{"en":"Who sees private materials?","ru":"Кто видит приватные материалы?","uz":"Yopiq materiallarni kim ko‘radi?"}},{"a":{"en":"This is a demo prototype. Centers, teachers, prices and materials are fictional; payment and authentication are simulated.","ru":"Это демо-прототип. Центры, преподаватели, цены и материалы вымышлены; оплата и аутентификация симулируются.","uz":"Bu demo prototip. Markazlar, o‘qituvchilar, narxlar va materiallar xayoliy; to‘lov va autentifikatsiya simulyatsiya qilinadi."},"id":"f7","q":{"en":"Is this a real platform?","ru":"Это настоящая платформа?","uz":"Bu haqiqiy platformami?"}}],"nav":[{"enabled":true,"id":"n-courses","label":{"en":"Courses","ru":"Курсы","uz":"Kurslar"},"path":"/courses"},{"enabled":true,"id":"n-teachers","label":{"en":"Teachers","ru":"Преподаватели","uz":"O‘qituvchilar"},"path":"/teachers"},{"enabled":true,"id":"n-builder","label":{"en":"Subscription","ru":"Абонемент","uz":"Abonement"},"path":"/builder"},{"enabled":true,"id":"n-how","label":{"en":"How it works","ru":"Как это работает","uz":"Qanday ishlaydi"},"path":"/how-it-works"},{"enabled":true,"id":"n-centers","label":{"en":"For centers","ru":"Для центров","uz":"Markazlar uchun"},"path":"/centers"},{"enabled":true,"id":"n-faq","label":{"en":"FAQ","ru":"FAQ","uz":"Savol-javob"},"path":"/faq"}],"pages":{"centers":[{"body":{"en":"ILMORA acts as a technical platform and marketing channel for centers. You define courses, groups and schedules; your teachers create content on their channels; students join your groups through the subscription.","ru":"ILMORA работает как техническая платформа и маркетинговый канал для центров. Вы определяете курсы, группы и расписание; ваши преподаватели создают контент на своих каналах; студенты присоединяются к вашим группам через абонемент.","uz":"ILMORA markazlar uchun texnik platforma va marketing kanali sifatida ishlaydi. Siz kurs, guruh va jadvalni belgilaysiz; o‘qituvchilaringiz o‘z kanalida kontent yaratadi; talabalar abonement orqali guruhlaringizga qo‘shiladi."},"enabled":true,"id":"c-hero","subtitle":{"en":"Add your courses to the ILMORA subscription and reach new students.","ru":"Добавьте свои курсы в абонемент ILMORA и найдите новых студентов.","uz":"Kurslaringizni ILMORA abonementiga qo‘shing va yangi talabalarga yeting."},"title":{"en":"For education centers","ru":"Для учебных центров","uz":"O‘quv markazlari uchun"},"type":"richText"},{"enabled":true,"id":"c-steps","items":[{"body":{"en":"Fill in the form below (demo).","ru":"Заполните форму ниже (демо).","uz":"Quyidagi formani to‘ldiring (demo)."},"id":"p1","title":{"en":"Inquiry","ru":"Запрос","uz":"So‘rov"}},{"body":{"en":"Your courses are entered using admin templates.","ru":"Ваши курсы вносятся по шаблонам админа.","uz":"Kurslaringiz admin shablonlari asosida kiritiladi."},"id":"p2","title":{"en":"Templates","ru":"Шаблоны","uz":"Shablonlar"}},{"body":{"en":"Teachers get their own channels.","ru":"Преподаватели получают свои каналы.","uz":"O‘qituvchilar o‘z kanalini oladi."},"id":"p3","title":{"en":"Channel","ru":"Канал","uz":"Kanal"}}],"subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Partnership steps","ru":"Шаги партнёрства","uz":"Hamkorlik qadamlari"},"type":"steps"},{"enabled":true,"id":"c-list","subtitle":{"en":"All fictional; no real partnerships exist.","ru":"Все вымышленные; реальных партнёрств нет.","uz":"Barchasi xayoliy; haqiqiy hamkorlik mavjud emas."},"title":{"en":"Sample centers","ru":"Демо-центры","uz":"Namuna markazlar"},"type":"centers"},{"enabled":true,"id":"c-form","subtitle":{"en":"Demo form: data is not stored or sent.","ru":"Демо-форма — данные не сохраняются и не отправляются.","uz":"Demo forma — ma’lumotlar saqlanmaydi va yuborilmaydi."},"title":{"en":"Leave an inquiry","ru":"Оставьте запрос","uz":"So‘rov qoldiring"},"type":"inquiryForm"}],"home":[{"enabled":true,"id":"h-hero","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"hero"},{"enabled":true,"id":"h-marquee","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Sample centers & categories","ru":"Демо-центры и направления","uz":"Namuna markazlar va yo‘nalishlar"},"type":"marquee"},{"enabled":true,"id":"h-packages","subtitle":{"en":"Study two or three courses at once. The monthly total is the sum of selected course prices, with no hidden fees.","ru":"Изучайте два или три курса одновременно. Месячная сумма — сумма цен выбранных курсов, без скрытых платежей.","uz":"Ikki yoki uchta kursni bir vaqtda o‘qing. Oylik summa — tanlangan kurslar narxlari yig‘indisi, yashirin to‘lovlarsiz."},"title":{"en":"Duo or Trio","ru":"Duo или Trio","uz":"Duo yoki Trio"},"type":"packages"},{"count":4,"enabled":true,"id":"h-featured","subtitle":{"en":"The most chosen courses from our sample centers.","ru":"Самые востребованные курсы демо-центров.","uz":"Namuna markazlarning eng ko‘p tanlanadigan kurslari."},"title":{"en":"Featured courses","ru":"Рекомендуемые курсы","uz":"Tavsiya etilgan kurslar"},"type":"featuredCourses"},{"enabled":true,"id":"h-furniture","subtitle":{"en":"Bazis is a hands-on furniture course: measurements, materials, fittings, 3D modeling and assembly. Workshop safety included.","ru":"Bazis — практический курс мебельного дела: замеры, материалы, фурнитура, 3D-моделирование и сборка. С безопасностью в мастерской.","uz":"Bazis — mebelsozlik bo‘yicha amaliy kurs: o‘lchov, material, furnitura, 3D modellashtirish va yig‘ish. Ustaxona xavfsizligi bilan."},"title":{"en":"From sketch to object","ru":"От эскиза до изделия","uz":"Eskizdan buyumgacha"},"type":"furnitureStory"},{"enabled":true,"id":"h-studio","subtitle":{"en":"A hands-on furniture programme: sketch, measurements, materials, fittings, 3D model and assembly, with your own project in the workshop.","ru":"Практическая программа по мебельному делу: эскиз, замеры, материалы, фурнитура, 3D-модель и сборка — с вашим собственным проектом, в мастерской.","uz":"Mebelsozlik bo‘yicha amaliy dastur: eskiz, o‘lchov, material, furnitura, 3D model va yig‘ish — o‘z loyihangiz bilan, ustaxonada."},"title":{"en":"The Bazis course","ru":"Курс Bazis","uz":"Bazis kursi"},"type":"studio3d"},{"enabled":true,"id":"h-categories","subtitle":{"en":"From languages to furniture making: eight categories across six sample centers.","ru":"От языков до мебельного дела — восемь направлений, шесть демо-центров.","uz":"Tildan mebelsozlikkacha — sakkiz yo‘nalish, olti namuna markaz."},"title":{"en":"Categories","ru":"Направления","uz":"Yo‘nalishlar"},"type":"categories"},{"count":4,"enabled":true,"id":"h-teachers","subtitle":{"en":"Courses, video lessons, playlists and resources in one channel.","ru":"Курсы, видеоуроки, плейлисты и материалы — в одном канале.","uz":"Kurslar, video darslar, pleylistlar va materiallar — bir kanalda."},"title":{"en":"Teachers & channels","ru":"Преподаватели и каналы","uz":"O‘qituvchilar va kanallar"},"type":"teachers"},{"enabled":true,"id":"h-how","items":[{"body":{"en":"Duo (2 courses) or Trio (3 courses).","ru":"Duo (2 курса) или Trio (3 курса).","uz":"Duo (2 kurs) yoki Trio (3 kurs)."},"id":"st1","title":{"en":"Choose a package","ru":"Выберите пакет","uz":"Paketni tanlang"}},{"body":{"en":"Schedule conflicts are detected automatically.","ru":"Конфликты расписания определяются автоматически.","uz":"Jadval to‘qnashuvlari avtomatik aniqlanadi."},"id":"st2","title":{"en":"Pick courses and groups","ru":"Выберите курс и группу","uz":"Kurs va guruhni tanlang"}},{"body":{"en":"Renew monthly and continue in your group.","ru":"Продлевайте каждый месяц — продолжайте в своей группе.","uz":"Har oy yangilang — guruhingizda davom eting."},"id":"st3","title":{"en":"Start learning","ru":"Начните учиться","uz":"O‘qishni boshlang"}}],"subtitle":{"en":"Three steps and you’re in a group.","ru":"Три шага — и вы в группе.","uz":"Uch qadam — va siz guruhdasiz."},"title":{"en":"How it works","ru":"Как это работает","uz":"Qanday ishlaydi"},"type":"howItWorks"},{"count":4,"enabled":true,"id":"h-faq","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Questions","ru":"Вопросы","uz":"Savollar"},"type":"faq"},{"enabled":true,"id":"h-centers","subtitle":{"en":"Leave an inquiry to add your courses to the ILMORA subscription.","ru":"Оставьте запрос, чтобы добавить свои курсы в абонемент ILMORA.","uz":"Kurslaringizni ILMORA abonementiga qo‘shish uchun so‘rov qoldiring."},"title":{"en":"Do you run an education center?","ru":"Вы руководите учебным центром?","uz":"O‘quv markazi rahbarimisiz?"},"type":"centerCta"}],"howItWorks":[{"body":{"en":"You join a specific group, follow a fixed schedule and continue when you renew. Every course price is transparent: the monthly total is the sum of selected course prices.","ru":"Вы присоединяетесь к конкретной группе, следуете фиксированному расписанию и продолжаете обучение при продлении. Цена каждого курса прозрачна — месячная сумма складывается из цен выбранных курсов.","uz":"Siz muayyan guruhga qo‘shilasiz, belgilangan jadvalga amal qilasiz va abonementni yangilaganingizda o‘qishni davom ettirasiz. Har bir kurs narxi shaffof — oylik summa tanlangan kurslar narxlari yig‘indisidan iborat."},"enabled":true,"id":"hw-hero","subtitle":{"en":"ILMORA gathers regular courses from different centers into one monthly subscription.","ru":"ILMORA объединяет регулярные курсы разных центров в один месячный абонемент.","uz":"ILMORA turli markazlarning muntazam kurslarini bitta oylik abonementga jamlaydi."},"title":{"en":"How it works","ru":"Как это работает","uz":"Qanday ishlaydi"},"type":"richText"},{"enabled":true,"id":"hw-steps","items":[{"body":{"en":"Duo is two courses, Trio is three. Limits are set by Super Admin.","ru":"Duo — два курса, Trio — три курса. Лимиты задаёт Супер-админ.","uz":"Duo — ikki kurs, Trio — uch kurs. Limitlar Super Admin tomonidan belgilanadi."},"id":"s1","title":{"en":"Package","ru":"Пакет","uz":"Paket"}},{"body":{"en":"Pick a group for each course. Duplicates and schedule conflicts are blocked.","ru":"Выберите группу для каждого курса. Дубликаты и конфликты расписания блокируются.","uz":"Har bir kurs uchun guruh tanlang. Takroriy tanlov va jadval to‘qnashuvi bloklanadi."},"id":"s2","title":{"en":"Courses","ru":"Курсы","uz":"Kurslar"}},{"body":{"en":"Renew monthly and continue in the same group. Your dashboard is generated from your selection.","ru":"Продлевайте каждый месяц и продолжайте в той же группе. Кабинет строится из вашего выбора.","uz":"Har oy yangilang va o‘sha guruhda davom eting. Kabinetingiz tanlovingizdan yaratiladi."},"id":"s3","title":{"en":"Renewal","ru":"Продление","uz":"Yangilash"}}],"subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Three steps","ru":"Три шага","uz":"Uch qadam"},"type":"steps"},{"enabled":true,"id":"hw-packages","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Packages","ru":"Пакеты","uz":"Paketlar"},"type":"packages"},{"count":6,"enabled":true,"id":"hw-faq","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"FAQ","ru":"FAQ","uz":"Savol-javob"},"type":"faq"}]}}'::jsonb, 'Approved local content transferred to production (2026-11-01)'
    FROM "SiteConfig" WHERE "tenantId" = t AND "data"->'brand' = '{"city":{"en":"Tashkent, Uzbekistan","ru":"г. Ташкент","uz":"Toşkent şahri"},"footerNote":{"en":"ILMORA is an education platform that brings Tashkent learning centers together in one subscription.","ru":"ILMORA — образовательная платформа, объединяющая учебные центры Ташкента в одном абонементе.","uz":"ILMORA — Toşkentdagi öquv markazlarini bitta abonementda birlaştiruvçi ta’lim platformasi."},"heroHeadline":{"en":"Different education centers. One subscription.","ru":"Разные учебные центры. Один абонемент.","uz":"Turli öquv markazlari. Bitta abonement."},"heroTagline":{"en":"One subscription. Many possibilities.","ru":"Один абонемент. Множество возможностей.","uz":"Bir abonement. Bir neçta imkoniyat."},"name":"ILMORA","primaryCta":{"en":"Choose courses","ru":"Выбрать курсы","uz":"Kurslarni tanlaş"}}'::jsonb AND "data"->'nav' = '[{"enabled":true,"id":"n-courses","label":{"en":"Courses","ru":"Курсы","uz":"Kurslar"},"path":"/courses"},{"enabled":true,"id":"n-teachers","label":{"en":"Teachers","ru":"Преподаватели","uz":"Öqituvçilar"},"path":"/teachers"},{"enabled":true,"id":"n-builder","label":{"en":"Subscription","ru":"Абонемент","uz":"Abonement"},"path":"/builder"},{"enabled":true,"id":"n-finder","label":{"en":"My set","ru":"Свой набор","uz":"Mening to’plamim"},"path":"/course-finder"},{"enabled":true,"id":"n-how","label":{"en":"How it works","ru":"Как это работает","uz":"Qanday işlaydi"},"path":"/how-it-works"},{"enabled":true,"id":"n-centers","label":{"en":"For centers","ru":"Для центров","uz":"Markazlar uçun"},"path":"/centers"},{"enabled":true,"id":"n-faq","label":{"en":"FAQ","ru":"FAQ","uz":"Savol-javob"},"path":"/faq"}]'::jsonb AND "data"->'pages' = '{"centers":[{"body":{"en":"ILMORA acts as a technical platform and marketing channel for centers. You define courses, groups and schedules; your teachers create content on their channels; students join your groups through the subscription.","ru":"ILMORA работает как техническая платформа и маркетинговый канал для центров. Вы определяете курсы, группы и расписание; ваши преподаватели создают контент на своих каналах; студенты присоединяются к вашим группам через абонемент.","uz":"ILMORA markazlar uçun texnik platforma va marketing kanali sifatida işlaydi. Siz kurs, guruh va jadvalni belgilaysiz; öqituvçilaringiz öz kanalida kontent yaratadi; talabalar abonement orqali guruhlaringizga qöşiladi."},"enabled":true,"id":"c-hero","subtitle":{"en":"Add your courses to the ILMORA subscription and reach new students.","ru":"Добавьте свои курсы в абонемент ILMORA и найдите новых студентов.","uz":"Kurslaringizni ILMORA abonementiga qöşing va yangi talabalarga yeting."},"title":{"en":"For education centers","ru":"Для учебных центров","uz":"Öquv markazlari uçun"},"type":"richText"},{"enabled":true,"id":"c-steps","items":[{"body":{"en":"Fill in the form below.","ru":"Заполните форму ниже.","uz":"Quyidagi formani töldiring."},"id":"p1","title":{"en":"Inquiry","ru":"Запрос","uz":"Sörov"}},{"body":{"en":"Your courses are entered using admin templates.","ru":"Ваши курсы вносятся по шаблонам админа.","uz":"Kurslaringiz admin şablonlari asosida kiritiladi."},"id":"p2","title":{"en":"Templates","ru":"Шаблоны","uz":"Şablonlar"}},{"body":{"en":"Teachers get their own channels.","ru":"Преподаватели получают свои каналы.","uz":"Öqituvçilar öz kanalini oladi."},"id":"p3","title":{"en":"Channel","ru":"Канал","uz":"Kanal"}}],"subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Partnership steps","ru":"Шаги партнёрства","uz":"Hamkorlik qadamlari"},"type":"steps"},{"enabled":true,"id":"c-list","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Centers","ru":"Центры","uz":"Markazlar"},"type":"centers"},{"enabled":true,"id":"c-form","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Leave an inquiry","ru":"Оставьте запрос","uz":"Sörov qoldiring"},"type":"inquiryForm"}],"home":[{"enabled":true,"id":"h-hero","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"hero"},{"enabled":true,"id":"h-discounts","subtitle":{"en":"Limited-time discounts on offline courses. The discounted price is calculated for you; the original price stays visible.","ru":"Временные скидки на офлайн-курсы. Цена со скидкой рассчитывается автоматически, исходная цена сохраняется.","uz":"Oflayn kurslarga vaqtinçalik çegirmalar. Çegirmali narx avtomatik hisoblanadi, asl narx saqlanadi."},"title":{"en":"Special Offers","ru":"Специальные предложения","uz":"Maxsus takliflar"},"type":"discounts"},{"enabled":true,"id":"h-marquee","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Centers & categories","ru":"Центры и направления","uz":"Markazlar va yönalişlar"},"type":"marquee"},{"enabled":true,"id":"h-packages","subtitle":{"en":"Flex is two courses, Winx is three, or build your own with 1 to 6 courses. The monthly total is the sum of selected course prices, with no hidden fees.","ru":"Flex — два курса, Winx — три курса или от 1 до 6 курсов на ваш выбор. Месячная сумма — сумма цен выбранных курсов, без скрытых платежей.","uz":"Flex — ikki kurs, Winx — uç kurs yoki 1 dan 6 tagaça kursni özingiz tanlang. Oylik summa — tanlangan kurslar narxlari yiğindisi, yaşirin tölovlarsiz."},"title":{"en":"Subscription packages","ru":"Пакеты абонемента","uz":"Abonement paketlari"},"type":"packages"},{"enabled":true,"id":"h-journey","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"journey"},{"enabled":true,"id":"h-finder","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"courseFinder"},{"count":4,"enabled":true,"id":"h-featured","subtitle":{"en":"The most chosen courses from our centers.","ru":"Самые востребованные курсы наших центров.","uz":"Markazlarimizning eng köp tanlanadigan kurslari."},"title":{"en":"Featured courses","ru":"Рекомендуемые курсы","uz":"Tavsiya etilgan kurslar"},"type":"featuredCourses"},{"enabled":true,"id":"h-furniture","subtitle":{"en":"Bazis is a hands-on furniture course: measurements, materials, fittings, 3D modeling and assembly. Workshop safety included.","ru":"Bazis — практический курс мебельного дела: замеры, материалы, фурнитура, 3D-моделирование и сборка. С безопасностью в мастерской.","uz":"Bazis — mebelsozlik böyiça amaliy kurs: ölçov, material, furnitura, 3D modellaştiriş va yiğiş. Ustaxona xavfsizligi bilan."},"title":{"en":"From sketch to object","ru":"От эскиза до изделия","uz":"Eskizdan buyumgaça"},"type":"furnitureStory"},{"enabled":true,"id":"h-studio","subtitle":{"en":"A hands-on furniture programme: sketch, measurements, materials, fittings, 3D model and assembly, with your own project in the workshop.","ru":"Практическая программа по мебельному делу: эскиз, замеры, материалы, фурнитура, 3D-модель и сборка — с вашим собственным проектом, в мастерской.","uz":"Mebelsozlik böyiça amaliy dastur: eskiz, ölçov, material, furnitura, 3D model va yiğiş — öz loyihangiz bilan, ustaxonada."},"title":{"en":"The Bazis course","ru":"Курс Bazis","uz":"Bazis kursi"},"type":"studio3d"},{"enabled":true,"id":"h-categories","subtitle":{"en":"From languages to furniture making: many categories across several centers.","ru":"От языков до мебельного дела — разные направления в нескольких центрах.","uz":"Tildan mebelsozlikkaça — turli yönalişlar, bir neçta markaz."},"title":{"en":"Categories","ru":"Направления","uz":"Yönalişlar"},"type":"categories"},{"count":4,"enabled":true,"id":"h-teachers","subtitle":{"en":"Courses, video lessons, playlists and resources in one channel.","ru":"Курсы, видеоуроки, плейлисты и материалы — в одном канале.","uz":"Kurslar, video darslar, pleylistlar va materiallar — bir kanalda."},"title":{"en":"Teachers & channels","ru":"Преподаватели и каналы","uz":"Öqituvçilar va kanallar"},"type":"teachers"},{"enabled":false,"id":"h-how","items":[{"body":{"en":"Flex (2 courses), Winx (3 courses) or Build Your Own (1–6 courses).","ru":"Flex (2 курса), Winx (3 курса) или «Собери свой пакет» (1–6 курсов).","uz":"Flex (2 kurs), Winx (3 kurs) yoki Mening to’plamim (1–6 kurs)."},"id":"st1","title":{"en":"Choose a package","ru":"Выберите пакет","uz":"Paketni tanlang"}},{"body":{"en":"Schedule conflicts are detected automatically.","ru":"Конфликты расписания определяются автоматически.","uz":"Jadval töqnaşuvlari avtomatik aniqlanadi."},"id":"st2","title":{"en":"Pick courses and groups","ru":"Выберите курс и группу","uz":"Kurs va guruhni tanlang"}},{"body":{"en":"Renew monthly and continue in your group.","ru":"Продлевайте каждый месяц — продолжайте в своей группе.","uz":"Har oy yangilang — guruhingizda davom eting."},"id":"st3","title":{"en":"Start learning","ru":"Начните учиться","uz":"Öqişni boşlang"}}],"subtitle":{"en":"Three steps and you’re in a group.","ru":"Три шага — и вы в группе.","uz":"Uç qadam — va siz guruhdasiz."},"title":{"en":"How it works","ru":"Как это работает","uz":"Qanday işlaydi"},"type":"howItWorks"},{"count":4,"enabled":true,"id":"h-faq","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Questions","ru":"Вопросы","uz":"Savollar"},"type":"faq"},{"enabled":true,"id":"h-centers","subtitle":{"en":"Leave an inquiry to add your courses to the ILMORA subscription.","ru":"Оставьте запрос, чтобы добавить свои курсы в абонемент ILMORA.","uz":"Kurslaringizni ILMORA abonementiga qöşiş uçun sörov qoldiring."},"title":{"en":"Do you run an education center?","ru":"Вы руководите учебным центром?","uz":"Öquv markazi rahbarimisiz?"},"type":"centerCta"}],"howItWorks":[{"body":{"en":"You join a specific group, follow a fixed schedule and continue when you renew. Every course price is transparent: the monthly total is the sum of selected course prices.","ru":"Вы присоединяетесь к конкретной группе, следуете фиксированному расписанию и продолжаете обучение при продлении. Цена каждого курса прозрачна — месячная сумма складывается из цен выбранных курсов.","uz":"Siz muayyan guruhga qöşilasiz, belgilangan jadvalga amal qilasiz va abonementni yangilaganingizda öqişni davom ettirasiz. Har bir kurs narxi şaffof — oylik summa tanlangan kurslar narxlari yiğindisidan iborat."},"enabled":true,"id":"hw-hero","subtitle":{"en":"ILMORA gathers regular courses from different centers into one monthly subscription.","ru":"ILMORA объединяет регулярные курсы разных центров в один месячный абонемент.","uz":"ILMORA turli markazlarning muntazam kurslarini bitta oylik abonementga jamlaydi."},"title":{"en":"How it works","ru":"Как это работает","uz":"Qanday işlaydi"},"type":"richText"},{"enabled":true,"id":"hw-journey","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"journey"},{"enabled":false,"id":"hw-steps","items":[{"body":{"en":"Flex is two courses, Winx is three, Build Your Own is 1 to 6. Limits are set by Super Admin.","ru":"Flex — два курса, Winx — три курса, «Собери свой пакет» — от 1 до 6 курсов. Лимиты задаёт Супер-админ.","uz":"Flex — ikki kurs, Winx — uç kurs, Mening to’plamim — 1 dan 6 tagaça kurs. Kurslar soni çegarasini Super Admin belgilaydi."},"id":"s1","title":{"en":"Package","ru":"Пакет","uz":"Paket"}},{"body":{"en":"Pick a group for each course. Duplicates and schedule conflicts are blocked.","ru":"Выберите группу для каждого курса. Дубликаты и конфликты расписания блокируются.","uz":"Har bir kurs uçun guruh tanlang. Takroriy tanlov va jadval töqnaşuvi bloklanadi."},"id":"s2","title":{"en":"Courses","ru":"Курсы","uz":"Kurslar"}},{"body":{"en":"Renew monthly and continue in the same group. Your dashboard is generated from your selection.","ru":"Продлевайте каждый месяц и продолжайте в той же группе. Кабинет строится из вашего выбора.","uz":"Har oy yangilang va öşa guruhda davom eting. Kabinetingiz tanlovingizdan yaratiladi."},"id":"s3","title":{"en":"Renewal","ru":"Продление","uz":"Yangilaş"}}],"subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Three steps","ru":"Три шага","uz":"Uç qadam"},"type":"steps"},{"enabled":true,"id":"hw-packages","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Packages","ru":"Пакеты","uz":"Paketlar"},"type":"packages"},{"count":6,"enabled":true,"id":"hw-faq","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"FAQ","ru":"FAQ","uz":"Savol-javob"},"type":"faq"}]}'::jsonb AND "data"->'faq' = '[{"a":{"en":"The monthly total is the sum of selected course prices. The package (Flex/Winx) only sets how many courses you take at once.","ru":"Месячная сумма — сумма цен выбранных курсов. Пакет (Flex/Winx) лишь определяет число одновременных курсов.","uz":"Oylik summa — tanlangan kurslar narxlarining yiğindisi. Paket (Flex/Winx) faqat bir vaqtdagi kurslar sonini belgilaydi."},"id":"f1","q":{"en":"How is the subscription price calculated?","ru":"Как рассчитывается цена абонемента?","uz":"Abonement narxi qanday hisoblanadi?"}},{"a":{"en":"No. Each course may appear once in a subscription; duplicates are blocked.","ru":"Нет. Каждый курс может быть в абонементе один раз; дубликаты блокируются.","uz":"Yöq. Har bir kurs abonementda bir marta bölişi mumkin; takroriy tanlov bloklanadi."},"id":"f2","q":{"en":"Can I select the same course twice?","ru":"Можно ли выбрать один курс дважды?","uz":"Bir kursni ikki marta tanlaş mumkinmi?"}},{"a":{"en":"The builder flags the conflict immediately and blocks activation. Choose another group.","ru":"Конструктор сразу показывает конфликт и не позволяет активировать. Выберите другую группу.","uz":"Abonement yiğuvçi töqnaşuvni darhol körsatadi va faollaştirişga ruxsat bermaydi. Boşqa guruhni tanlang."},"id":"f3","q":{"en":"What if schedules overlap?","ru":"Что если расписания пересекаются?","uz":"Jadval töqnaşsa nima böladi?"}},{"a":{"en":"Yes. When you renew, you continue in the same groups.","ru":"Да. При продлении вы продолжаете обучение в тех же группах.","uz":"Ha. Yangilaganda siz öşa guruhlarda öqişni davom ettirasiz."},"id":"f4","q":{"en":"Do I keep my group when I renew?","ru":"Сохраняется ли моя группа при продлении?","uz":"Yangilaganda guruhim saqlanib qoladimi?"}},{"a":{"en":"No. Visibility and enrollment are separate: a public page or video doesn’t grant a seat in a paid group.","ru":"Нет. Видимость и зачисление разделены: публичная страница или видео не даёт места в платной группе.","uz":"Yöq. Köriniş va röyxatdan ötiş alohida: ommaviy sahifa yoki video pullik guruhda örin bermaydi."},"id":"f5","q":{"en":"Does a public video give free course access?","ru":"Даёт ли публичное видео бесплатный доступ к курсу?","uz":"Ommaviy video kursga bepul kiriş beradimi?"}},{"a":{"en":"Only the teacher, authorized Super Admin, and the students or groups the teacher selected.","ru":"Только преподаватель, уполномоченный Супер-админ и выбранные преподавателем студенты или группы.","uz":"Faqat öqituvçi, vakolatli Super Admin va öqituvçi tanlagan talabalar yoki guruhlar."},"id":"f6","q":{"en":"Who sees private materials?","ru":"Кто видит приватные материалы?","uz":"Yopiq materiallarni kim köradi?"}}]'::jsonb AND "data"->'announcements' = '[{"audience":"all","body":{"en":"Seats in new Bazis and Frontend groups are limited.","ru":"Места в новых группах Bazis и Frontend ограничены.","uz":"Bazis va Frontend kurslarida yangi guruhlar uçun örinlar çeklangan."},"enabled":true,"id":"a1","title":{"en":"October groups are open","ru":"Открыты группы на октябрь","uz":"Oktyabr guruhlari oçildi"}},{"audience":"teachers","body":{"en":"Remember to select an audience for private materials.","ru":"Не забывайте выбирать аудиторию для приватных материалов.","uz":"Yopiq materiallar uçun auditoriya tanlaşni unutmang."},"enabled":true,"id":"a2","title":{"en":"For teachers: visibility settings","ru":"Для преподавателей: настройки видимости","uz":"Öqituvçilar uçun: köriniş sozlamalari"}}]'::jsonb
    ON CONFLICT ("id") DO NOTHING;
    UPDATE "SiteConfig" SET "data" = "data" || '{"announcements":[{"audience":"all","body":{"en":"Seats in new Bazis and Frontend groups are limited (demo announcement).","ru":"Места в новых группах Bazis и Frontend ограничены (демо-объявление).","uz":"Bazis va Frontend kurslarida yangi guruhlar uchun o‘rinlar cheklangan (demo e’lon)."},"enabled":true,"id":"a1","title":{"en":"October groups are open","ru":"Открыты группы на октябрь","uz":"Oktyabr guruhlari ochildi"}},{"audience":"teachers","body":{"en":"Remember to select an audience for private materials.","ru":"Не забывайте выбирать аудиторию для приватных материалов.","uz":"Yopiq materiallar uchun auditoriya tanlashni unutmang."},"enabled":true,"id":"a2","title":{"en":"For teachers: visibility settings","ru":"Для преподавателей: настройки видимости","uz":"O‘qituvchilar uchun: ko‘rinish sozlamalari"}}],"brand":{"city":{"en":"Tashkent, Uzbekistan","ru":"Ташкент, Узбекистан","uz":"Toshkent, O‘zbekiston"},"footerNote":{"en":"ILMORA is a sample education platform for education centers in Tashkent. This is a demo prototype: all centers, teachers, prices and materials are fictional.","ru":"ILMORA — демонстрационная образовательная платформа для учебных центров Ташкента. Это демо-прототип: все центры, преподаватели, цены и материалы вымышлены.","uz":"ILMORA — Toshkentdagi o‘quv markazlari uchun namuna ta’lim platformasi. Bu demo prototip: barcha markazlar, o‘qituvchilar, narxlar va materiallar xayoliy."},"heroHeadline":{"en":"Different education centers. One subscription.","ru":"Разные учебные центры. Один абонемент.","uz":"Turli o‘quv markazlari. Bitta abonement."},"heroTagline":{"en":"One subscription. Many possibilities.","ru":"Один абонемент. Множество возможностей.","uz":"Bir abonement. Bir nechta imkoniyat."},"name":"ILMORA","primaryCta":{"en":"Choose courses","ru":"Выбрать курсы","uz":"Kurslarni tanlash"}},"faq":[{"a":{"en":"The monthly total is the sum of selected course prices. The package (Duo/Trio) only sets how many courses you take at once.","ru":"Месячная сумма — сумма цен выбранных курсов. Пакет (Duo/Trio) лишь определяет число одновременных курсов.","uz":"Oylik summa — tanlangan kurslar narxlarining yig‘indisi. Paket (Duo/Trio) faqat bir vaqtdagi kurslar sonini belgilaydi."},"id":"f1","q":{"en":"How is the subscription price calculated?","ru":"Как рассчитывается цена абонемента?","uz":"Abonement narxi qanday hisoblanadi?"}},{"a":{"en":"No. Each course may appear once in a subscription; duplicates are blocked.","ru":"Нет. Каждый курс может быть в абонементе один раз; дубликаты блокируются.","uz":"Yo‘q. Har bir kurs abonementda bir marta bo‘lishi mumkin; takroriy tanlov bloklanadi."},"id":"f2","q":{"en":"Can I select the same course twice?","ru":"Можно ли выбрать один курс дважды?","uz":"Bir kursni ikki marta tanlash mumkinmi?"}},{"a":{"en":"The builder flags the conflict immediately and blocks activation. Choose another group.","ru":"Конструктор сразу показывает конфликт и не позволяет активировать. Выберите другую группу.","uz":"Abonement yig‘uvchi to‘qnashuvni darhol ko‘rsatadi va faollashtirishga ruxsat bermaydi. Boshqa guruhni tanlang."},"id":"f3","q":{"en":"What if schedules overlap?","ru":"Что если расписания пересекаются?","uz":"Jadval to‘qnashsa nima bo‘ladi?"}},{"a":{"en":"Yes. When you renew, you continue in the same groups.","ru":"Да. При продлении вы продолжаете обучение в тех же группах.","uz":"Ha. Yangilaganda siz o‘sha guruhlarda o‘qishni davom ettirasiz."},"id":"f4","q":{"en":"Do I keep my group when I renew?","ru":"Сохраняется ли моя группа при продлении?","uz":"Yangilaganda guruhim saqlanib qoladimi?"}},{"a":{"en":"No. Visibility and enrollment are separate: a public page or video doesn’t grant a seat in a paid group.","ru":"Нет. Видимость и зачисление разделены: публичная страница или видео не даёт места в платной группе.","uz":"Yo‘q. Ko‘rinish va ro‘yxatdan o‘tish alohida: ommaviy sahifa yoki video pullik guruhda o‘rin bermaydi."},"id":"f5","q":{"en":"Does a public video give free course access?","ru":"Даёт ли публичное видео бесплатный доступ к курсу?","uz":"Ommaviy video kursga bepul kirish beradimi?"}},{"a":{"en":"Only the teacher, authorized Super Admin, and the students or groups the teacher selected.","ru":"Только преподаватель, уполномоченный Супер-админ и выбранные преподавателем студенты или группы.","uz":"Faqat o‘qituvchi, vakolatli Super Admin va o‘qituvchi tanlagan talabalar yoki guruhlar."},"id":"f6","q":{"en":"Who sees private materials?","ru":"Кто видит приватные материалы?","uz":"Yopiq materiallarni kim ko‘radi?"}},{"a":{"en":"This is a demo prototype. Centers, teachers, prices and materials are fictional; payment and authentication are simulated.","ru":"Это демо-прототип. Центры, преподаватели, цены и материалы вымышлены; оплата и аутентификация симулируются.","uz":"Bu demo prototip. Markazlar, o‘qituvchilar, narxlar va materiallar xayoliy; to‘lov va autentifikatsiya simulyatsiya qilinadi."},"id":"f7","q":{"en":"Is this a real platform?","ru":"Это настоящая платформа?","uz":"Bu haqiqiy platformami?"}}],"nav":[{"enabled":true,"id":"n-courses","label":{"en":"Courses","ru":"Курсы","uz":"Kurslar"},"path":"/courses"},{"enabled":true,"id":"n-teachers","label":{"en":"Teachers","ru":"Преподаватели","uz":"O‘qituvchilar"},"path":"/teachers"},{"enabled":true,"id":"n-builder","label":{"en":"Subscription","ru":"Абонемент","uz":"Abonement"},"path":"/builder"},{"enabled":true,"id":"n-how","label":{"en":"How it works","ru":"Как это работает","uz":"Qanday ishlaydi"},"path":"/how-it-works"},{"enabled":true,"id":"n-centers","label":{"en":"For centers","ru":"Для центров","uz":"Markazlar uchun"},"path":"/centers"},{"enabled":true,"id":"n-faq","label":{"en":"FAQ","ru":"FAQ","uz":"Savol-javob"},"path":"/faq"}],"pages":{"centers":[{"body":{"en":"ILMORA acts as a technical platform and marketing channel for centers. You define courses, groups and schedules; your teachers create content on their channels; students join your groups through the subscription.","ru":"ILMORA работает как техническая платформа и маркетинговый канал для центров. Вы определяете курсы, группы и расписание; ваши преподаватели создают контент на своих каналах; студенты присоединяются к вашим группам через абонемент.","uz":"ILMORA markazlar uchun texnik platforma va marketing kanali sifatida ishlaydi. Siz kurs, guruh va jadvalni belgilaysiz; o‘qituvchilaringiz o‘z kanalida kontent yaratadi; talabalar abonement orqali guruhlaringizga qo‘shiladi."},"enabled":true,"id":"c-hero","subtitle":{"en":"Add your courses to the ILMORA subscription and reach new students.","ru":"Добавьте свои курсы в абонемент ILMORA и найдите новых студентов.","uz":"Kurslaringizni ILMORA abonementiga qo‘shing va yangi talabalarga yeting."},"title":{"en":"For education centers","ru":"Для учебных центров","uz":"O‘quv markazlari uchun"},"type":"richText"},{"enabled":true,"id":"c-steps","items":[{"body":{"en":"Fill in the form below (demo).","ru":"Заполните форму ниже (демо).","uz":"Quyidagi formani to‘ldiring (demo)."},"id":"p1","title":{"en":"Inquiry","ru":"Запрос","uz":"So‘rov"}},{"body":{"en":"Your courses are entered using admin templates.","ru":"Ваши курсы вносятся по шаблонам админа.","uz":"Kurslaringiz admin shablonlari asosida kiritiladi."},"id":"p2","title":{"en":"Templates","ru":"Шаблоны","uz":"Shablonlar"}},{"body":{"en":"Teachers get their own channels.","ru":"Преподаватели получают свои каналы.","uz":"O‘qituvchilar o‘z kanalini oladi."},"id":"p3","title":{"en":"Channel","ru":"Канал","uz":"Kanal"}}],"subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Partnership steps","ru":"Шаги партнёрства","uz":"Hamkorlik qadamlari"},"type":"steps"},{"enabled":true,"id":"c-list","subtitle":{"en":"All fictional; no real partnerships exist.","ru":"Все вымышленные; реальных партнёрств нет.","uz":"Barchasi xayoliy; haqiqiy hamkorlik mavjud emas."},"title":{"en":"Sample centers","ru":"Демо-центры","uz":"Namuna markazlar"},"type":"centers"},{"enabled":true,"id":"c-form","subtitle":{"en":"Demo form: data is not stored or sent.","ru":"Демо-форма — данные не сохраняются и не отправляются.","uz":"Demo forma — ma’lumotlar saqlanmaydi va yuborilmaydi."},"title":{"en":"Leave an inquiry","ru":"Оставьте запрос","uz":"So‘rov qoldiring"},"type":"inquiryForm"}],"home":[{"enabled":true,"id":"h-hero","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"hero"},{"enabled":true,"id":"h-marquee","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Sample centers & categories","ru":"Демо-центры и направления","uz":"Namuna markazlar va yo‘nalishlar"},"type":"marquee"},{"enabled":true,"id":"h-packages","subtitle":{"en":"Study two or three courses at once. The monthly total is the sum of selected course prices, with no hidden fees.","ru":"Изучайте два или три курса одновременно. Месячная сумма — сумма цен выбранных курсов, без скрытых платежей.","uz":"Ikki yoki uchta kursni bir vaqtda o‘qing. Oylik summa — tanlangan kurslar narxlari yig‘indisi, yashirin to‘lovlarsiz."},"title":{"en":"Duo or Trio","ru":"Duo или Trio","uz":"Duo yoki Trio"},"type":"packages"},{"count":4,"enabled":true,"id":"h-featured","subtitle":{"en":"The most chosen courses from our sample centers.","ru":"Самые востребованные курсы демо-центров.","uz":"Namuna markazlarning eng ko‘p tanlanadigan kurslari."},"title":{"en":"Featured courses","ru":"Рекомендуемые курсы","uz":"Tavsiya etilgan kurslar"},"type":"featuredCourses"},{"enabled":true,"id":"h-furniture","subtitle":{"en":"Bazis is a hands-on furniture course: measurements, materials, fittings, 3D modeling and assembly. Workshop safety included.","ru":"Bazis — практический курс мебельного дела: замеры, материалы, фурнитура, 3D-моделирование и сборка. С безопасностью в мастерской.","uz":"Bazis — mebelsozlik bo‘yicha amaliy kurs: o‘lchov, material, furnitura, 3D modellashtirish va yig‘ish. Ustaxona xavfsizligi bilan."},"title":{"en":"From sketch to object","ru":"От эскиза до изделия","uz":"Eskizdan buyumgacha"},"type":"furnitureStory"},{"enabled":true,"id":"h-studio","subtitle":{"en":"A hands-on furniture programme: sketch, measurements, materials, fittings, 3D model and assembly, with your own project in the workshop.","ru":"Практическая программа по мебельному делу: эскиз, замеры, материалы, фурнитура, 3D-модель и сборка — с вашим собственным проектом, в мастерской.","uz":"Mebelsozlik bo‘yicha amaliy dastur: eskiz, o‘lchov, material, furnitura, 3D model va yig‘ish — o‘z loyihangiz bilan, ustaxonada."},"title":{"en":"The Bazis course","ru":"Курс Bazis","uz":"Bazis kursi"},"type":"studio3d"},{"enabled":true,"id":"h-categories","subtitle":{"en":"From languages to furniture making: eight categories across six sample centers.","ru":"От языков до мебельного дела — восемь направлений, шесть демо-центров.","uz":"Tildan mebelsozlikkacha — sakkiz yo‘nalish, olti namuna markaz."},"title":{"en":"Categories","ru":"Направления","uz":"Yo‘nalishlar"},"type":"categories"},{"count":4,"enabled":true,"id":"h-teachers","subtitle":{"en":"Courses, video lessons, playlists and resources in one channel.","ru":"Курсы, видеоуроки, плейлисты и материалы — в одном канале.","uz":"Kurslar, video darslar, pleylistlar va materiallar — bir kanalda."},"title":{"en":"Teachers & channels","ru":"Преподаватели и каналы","uz":"O‘qituvchilar va kanallar"},"type":"teachers"},{"enabled":true,"id":"h-how","items":[{"body":{"en":"Duo (2 courses) or Trio (3 courses).","ru":"Duo (2 курса) или Trio (3 курса).","uz":"Duo (2 kurs) yoki Trio (3 kurs)."},"id":"st1","title":{"en":"Choose a package","ru":"Выберите пакет","uz":"Paketni tanlang"}},{"body":{"en":"Schedule conflicts are detected automatically.","ru":"Конфликты расписания определяются автоматически.","uz":"Jadval to‘qnashuvlari avtomatik aniqlanadi."},"id":"st2","title":{"en":"Pick courses and groups","ru":"Выберите курс и группу","uz":"Kurs va guruhni tanlang"}},{"body":{"en":"Renew monthly and continue in your group.","ru":"Продлевайте каждый месяц — продолжайте в своей группе.","uz":"Har oy yangilang — guruhingizda davom eting."},"id":"st3","title":{"en":"Start learning","ru":"Начните учиться","uz":"O‘qishni boshlang"}}],"subtitle":{"en":"Three steps and you’re in a group.","ru":"Три шага — и вы в группе.","uz":"Uch qadam — va siz guruhdasiz."},"title":{"en":"How it works","ru":"Как это работает","uz":"Qanday ishlaydi"},"type":"howItWorks"},{"count":4,"enabled":true,"id":"h-faq","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Questions","ru":"Вопросы","uz":"Savollar"},"type":"faq"},{"enabled":true,"id":"h-centers","subtitle":{"en":"Leave an inquiry to add your courses to the ILMORA subscription.","ru":"Оставьте запрос, чтобы добавить свои курсы в абонемент ILMORA.","uz":"Kurslaringizni ILMORA abonementiga qo‘shish uchun so‘rov qoldiring."},"title":{"en":"Do you run an education center?","ru":"Вы руководите учебным центром?","uz":"O‘quv markazi rahbarimisiz?"},"type":"centerCta"}],"howItWorks":[{"body":{"en":"You join a specific group, follow a fixed schedule and continue when you renew. Every course price is transparent: the monthly total is the sum of selected course prices.","ru":"Вы присоединяетесь к конкретной группе, следуете фиксированному расписанию и продолжаете обучение при продлении. Цена каждого курса прозрачна — месячная сумма складывается из цен выбранных курсов.","uz":"Siz muayyan guruhga qo‘shilasiz, belgilangan jadvalga amal qilasiz va abonementni yangilaganingizda o‘qishni davom ettirasiz. Har bir kurs narxi shaffof — oylik summa tanlangan kurslar narxlari yig‘indisidan iborat."},"enabled":true,"id":"hw-hero","subtitle":{"en":"ILMORA gathers regular courses from different centers into one monthly subscription.","ru":"ILMORA объединяет регулярные курсы разных центров в один месячный абонемент.","uz":"ILMORA turli markazlarning muntazam kurslarini bitta oylik abonementga jamlaydi."},"title":{"en":"How it works","ru":"Как это работает","uz":"Qanday ishlaydi"},"type":"richText"},{"enabled":true,"id":"hw-steps","items":[{"body":{"en":"Duo is two courses, Trio is three. Limits are set by Super Admin.","ru":"Duo — два курса, Trio — три курса. Лимиты задаёт Супер-админ.","uz":"Duo — ikki kurs, Trio — uch kurs. Limitlar Super Admin tomonidan belgilanadi."},"id":"s1","title":{"en":"Package","ru":"Пакет","uz":"Paket"}},{"body":{"en":"Pick a group for each course. Duplicates and schedule conflicts are blocked.","ru":"Выберите группу для каждого курса. Дубликаты и конфликты расписания блокируются.","uz":"Har bir kurs uchun guruh tanlang. Takroriy tanlov va jadval to‘qnashuvi bloklanadi."},"id":"s2","title":{"en":"Courses","ru":"Курсы","uz":"Kurslar"}},{"body":{"en":"Renew monthly and continue in the same group. Your dashboard is generated from your selection.","ru":"Продлевайте каждый месяц и продолжайте в той же группе. Кабинет строится из вашего выбора.","uz":"Har oy yangilang va o‘sha guruhda davom eting. Kabinetingiz tanlovingizdan yaratiladi."},"id":"s3","title":{"en":"Renewal","ru":"Продление","uz":"Yangilash"}}],"subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Three steps","ru":"Три шага","uz":"Uch qadam"},"type":"steps"},{"enabled":true,"id":"hw-packages","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Packages","ru":"Пакеты","uz":"Paketlar"},"type":"packages"},{"count":6,"enabled":true,"id":"hw-faq","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"FAQ","ru":"FAQ","uz":"Savol-javob"},"type":"faq"}]}}'::jsonb, "version" = "version" + 1, "updatedAt" = now() WHERE "tenantId" = t AND "data"->'brand' = '{"city":{"en":"Tashkent, Uzbekistan","ru":"г. Ташкент","uz":"Toşkent şahri"},"footerNote":{"en":"ILMORA is an education platform that brings Tashkent learning centers together in one subscription.","ru":"ILMORA — образовательная платформа, объединяющая учебные центры Ташкента в одном абонементе.","uz":"ILMORA — Toşkentdagi öquv markazlarini bitta abonementda birlaştiruvçi ta’lim platformasi."},"heroHeadline":{"en":"Different education centers. One subscription.","ru":"Разные учебные центры. Один абонемент.","uz":"Turli öquv markazlari. Bitta abonement."},"heroTagline":{"en":"One subscription. Many possibilities.","ru":"Один абонемент. Множество возможностей.","uz":"Bir abonement. Bir neçta imkoniyat."},"name":"ILMORA","primaryCta":{"en":"Choose courses","ru":"Выбрать курсы","uz":"Kurslarni tanlaş"}}'::jsonb AND "data"->'nav' = '[{"enabled":true,"id":"n-courses","label":{"en":"Courses","ru":"Курсы","uz":"Kurslar"},"path":"/courses"},{"enabled":true,"id":"n-teachers","label":{"en":"Teachers","ru":"Преподаватели","uz":"Öqituvçilar"},"path":"/teachers"},{"enabled":true,"id":"n-builder","label":{"en":"Subscription","ru":"Абонемент","uz":"Abonement"},"path":"/builder"},{"enabled":true,"id":"n-finder","label":{"en":"My set","ru":"Свой набор","uz":"Mening to’plamim"},"path":"/course-finder"},{"enabled":true,"id":"n-how","label":{"en":"How it works","ru":"Как это работает","uz":"Qanday işlaydi"},"path":"/how-it-works"},{"enabled":true,"id":"n-centers","label":{"en":"For centers","ru":"Для центров","uz":"Markazlar uçun"},"path":"/centers"},{"enabled":true,"id":"n-faq","label":{"en":"FAQ","ru":"FAQ","uz":"Savol-javob"},"path":"/faq"}]'::jsonb AND "data"->'pages' = '{"centers":[{"body":{"en":"ILMORA acts as a technical platform and marketing channel for centers. You define courses, groups and schedules; your teachers create content on their channels; students join your groups through the subscription.","ru":"ILMORA работает как техническая платформа и маркетинговый канал для центров. Вы определяете курсы, группы и расписание; ваши преподаватели создают контент на своих каналах; студенты присоединяются к вашим группам через абонемент.","uz":"ILMORA markazlar uçun texnik platforma va marketing kanali sifatida işlaydi. Siz kurs, guruh va jadvalni belgilaysiz; öqituvçilaringiz öz kanalida kontent yaratadi; talabalar abonement orqali guruhlaringizga qöşiladi."},"enabled":true,"id":"c-hero","subtitle":{"en":"Add your courses to the ILMORA subscription and reach new students.","ru":"Добавьте свои курсы в абонемент ILMORA и найдите новых студентов.","uz":"Kurslaringizni ILMORA abonementiga qöşing va yangi talabalarga yeting."},"title":{"en":"For education centers","ru":"Для учебных центров","uz":"Öquv markazlari uçun"},"type":"richText"},{"enabled":true,"id":"c-steps","items":[{"body":{"en":"Fill in the form below.","ru":"Заполните форму ниже.","uz":"Quyidagi formani töldiring."},"id":"p1","title":{"en":"Inquiry","ru":"Запрос","uz":"Sörov"}},{"body":{"en":"Your courses are entered using admin templates.","ru":"Ваши курсы вносятся по шаблонам админа.","uz":"Kurslaringiz admin şablonlari asosida kiritiladi."},"id":"p2","title":{"en":"Templates","ru":"Шаблоны","uz":"Şablonlar"}},{"body":{"en":"Teachers get their own channels.","ru":"Преподаватели получают свои каналы.","uz":"Öqituvçilar öz kanalini oladi."},"id":"p3","title":{"en":"Channel","ru":"Канал","uz":"Kanal"}}],"subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Partnership steps","ru":"Шаги партнёрства","uz":"Hamkorlik qadamlari"},"type":"steps"},{"enabled":true,"id":"c-list","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Centers","ru":"Центры","uz":"Markazlar"},"type":"centers"},{"enabled":true,"id":"c-form","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Leave an inquiry","ru":"Оставьте запрос","uz":"Sörov qoldiring"},"type":"inquiryForm"}],"home":[{"enabled":true,"id":"h-hero","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"hero"},{"enabled":true,"id":"h-discounts","subtitle":{"en":"Limited-time discounts on offline courses. The discounted price is calculated for you; the original price stays visible.","ru":"Временные скидки на офлайн-курсы. Цена со скидкой рассчитывается автоматически, исходная цена сохраняется.","uz":"Oflayn kurslarga vaqtinçalik çegirmalar. Çegirmali narx avtomatik hisoblanadi, asl narx saqlanadi."},"title":{"en":"Special Offers","ru":"Специальные предложения","uz":"Maxsus takliflar"},"type":"discounts"},{"enabled":true,"id":"h-marquee","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Centers & categories","ru":"Центры и направления","uz":"Markazlar va yönalişlar"},"type":"marquee"},{"enabled":true,"id":"h-packages","subtitle":{"en":"Flex is two courses, Winx is three, or build your own with 1 to 6 courses. The monthly total is the sum of selected course prices, with no hidden fees.","ru":"Flex — два курса, Winx — три курса или от 1 до 6 курсов на ваш выбор. Месячная сумма — сумма цен выбранных курсов, без скрытых платежей.","uz":"Flex — ikki kurs, Winx — uç kurs yoki 1 dan 6 tagaça kursni özingiz tanlang. Oylik summa — tanlangan kurslar narxlari yiğindisi, yaşirin tölovlarsiz."},"title":{"en":"Subscription packages","ru":"Пакеты абонемента","uz":"Abonement paketlari"},"type":"packages"},{"enabled":true,"id":"h-journey","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"journey"},{"enabled":true,"id":"h-finder","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"courseFinder"},{"count":4,"enabled":true,"id":"h-featured","subtitle":{"en":"The most chosen courses from our centers.","ru":"Самые востребованные курсы наших центров.","uz":"Markazlarimizning eng köp tanlanadigan kurslari."},"title":{"en":"Featured courses","ru":"Рекомендуемые курсы","uz":"Tavsiya etilgan kurslar"},"type":"featuredCourses"},{"enabled":true,"id":"h-furniture","subtitle":{"en":"Bazis is a hands-on furniture course: measurements, materials, fittings, 3D modeling and assembly. Workshop safety included.","ru":"Bazis — практический курс мебельного дела: замеры, материалы, фурнитура, 3D-моделирование и сборка. С безопасностью в мастерской.","uz":"Bazis — mebelsozlik böyiça amaliy kurs: ölçov, material, furnitura, 3D modellaştiriş va yiğiş. Ustaxona xavfsizligi bilan."},"title":{"en":"From sketch to object","ru":"От эскиза до изделия","uz":"Eskizdan buyumgaça"},"type":"furnitureStory"},{"enabled":true,"id":"h-studio","subtitle":{"en":"A hands-on furniture programme: sketch, measurements, materials, fittings, 3D model and assembly, with your own project in the workshop.","ru":"Практическая программа по мебельному делу: эскиз, замеры, материалы, фурнитура, 3D-модель и сборка — с вашим собственным проектом, в мастерской.","uz":"Mebelsozlik böyiça amaliy dastur: eskiz, ölçov, material, furnitura, 3D model va yiğiş — öz loyihangiz bilan, ustaxonada."},"title":{"en":"The Bazis course","ru":"Курс Bazis","uz":"Bazis kursi"},"type":"studio3d"},{"enabled":true,"id":"h-categories","subtitle":{"en":"From languages to furniture making: many categories across several centers.","ru":"От языков до мебельного дела — разные направления в нескольких центрах.","uz":"Tildan mebelsozlikkaça — turli yönalişlar, bir neçta markaz."},"title":{"en":"Categories","ru":"Направления","uz":"Yönalişlar"},"type":"categories"},{"count":4,"enabled":true,"id":"h-teachers","subtitle":{"en":"Courses, video lessons, playlists and resources in one channel.","ru":"Курсы, видеоуроки, плейлисты и материалы — в одном канале.","uz":"Kurslar, video darslar, pleylistlar va materiallar — bir kanalda."},"title":{"en":"Teachers & channels","ru":"Преподаватели и каналы","uz":"Öqituvçilar va kanallar"},"type":"teachers"},{"enabled":false,"id":"h-how","items":[{"body":{"en":"Flex (2 courses), Winx (3 courses) or Build Your Own (1–6 courses).","ru":"Flex (2 курса), Winx (3 курса) или «Собери свой пакет» (1–6 курсов).","uz":"Flex (2 kurs), Winx (3 kurs) yoki Mening to’plamim (1–6 kurs)."},"id":"st1","title":{"en":"Choose a package","ru":"Выберите пакет","uz":"Paketni tanlang"}},{"body":{"en":"Schedule conflicts are detected automatically.","ru":"Конфликты расписания определяются автоматически.","uz":"Jadval töqnaşuvlari avtomatik aniqlanadi."},"id":"st2","title":{"en":"Pick courses and groups","ru":"Выберите курс и группу","uz":"Kurs va guruhni tanlang"}},{"body":{"en":"Renew monthly and continue in your group.","ru":"Продлевайте каждый месяц — продолжайте в своей группе.","uz":"Har oy yangilang — guruhingizda davom eting."},"id":"st3","title":{"en":"Start learning","ru":"Начните учиться","uz":"Öqişni boşlang"}}],"subtitle":{"en":"Three steps and you’re in a group.","ru":"Три шага — и вы в группе.","uz":"Uç qadam — va siz guruhdasiz."},"title":{"en":"How it works","ru":"Как это работает","uz":"Qanday işlaydi"},"type":"howItWorks"},{"count":4,"enabled":true,"id":"h-faq","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Questions","ru":"Вопросы","uz":"Savollar"},"type":"faq"},{"enabled":true,"id":"h-centers","subtitle":{"en":"Leave an inquiry to add your courses to the ILMORA subscription.","ru":"Оставьте запрос, чтобы добавить свои курсы в абонемент ILMORA.","uz":"Kurslaringizni ILMORA abonementiga qöşiş uçun sörov qoldiring."},"title":{"en":"Do you run an education center?","ru":"Вы руководите учебным центром?","uz":"Öquv markazi rahbarimisiz?"},"type":"centerCta"}],"howItWorks":[{"body":{"en":"You join a specific group, follow a fixed schedule and continue when you renew. Every course price is transparent: the monthly total is the sum of selected course prices.","ru":"Вы присоединяетесь к конкретной группе, следуете фиксированному расписанию и продолжаете обучение при продлении. Цена каждого курса прозрачна — месячная сумма складывается из цен выбранных курсов.","uz":"Siz muayyan guruhga qöşilasiz, belgilangan jadvalga amal qilasiz va abonementni yangilaganingizda öqişni davom ettirasiz. Har bir kurs narxi şaffof — oylik summa tanlangan kurslar narxlari yiğindisidan iborat."},"enabled":true,"id":"hw-hero","subtitle":{"en":"ILMORA gathers regular courses from different centers into one monthly subscription.","ru":"ILMORA объединяет регулярные курсы разных центров в один месячный абонемент.","uz":"ILMORA turli markazlarning muntazam kurslarini bitta oylik abonementga jamlaydi."},"title":{"en":"How it works","ru":"Как это работает","uz":"Qanday işlaydi"},"type":"richText"},{"enabled":true,"id":"hw-journey","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"","ru":"","uz":""},"type":"journey"},{"enabled":false,"id":"hw-steps","items":[{"body":{"en":"Flex is two courses, Winx is three, Build Your Own is 1 to 6. Limits are set by Super Admin.","ru":"Flex — два курса, Winx — три курса, «Собери свой пакет» — от 1 до 6 курсов. Лимиты задаёт Супер-админ.","uz":"Flex — ikki kurs, Winx — uç kurs, Mening to’plamim — 1 dan 6 tagaça kurs. Kurslar soni çegarasini Super Admin belgilaydi."},"id":"s1","title":{"en":"Package","ru":"Пакет","uz":"Paket"}},{"body":{"en":"Pick a group for each course. Duplicates and schedule conflicts are blocked.","ru":"Выберите группу для каждого курса. Дубликаты и конфликты расписания блокируются.","uz":"Har bir kurs uçun guruh tanlang. Takroriy tanlov va jadval töqnaşuvi bloklanadi."},"id":"s2","title":{"en":"Courses","ru":"Курсы","uz":"Kurslar"}},{"body":{"en":"Renew monthly and continue in the same group. Your dashboard is generated from your selection.","ru":"Продлевайте каждый месяц и продолжайте в той же группе. Кабинет строится из вашего выбора.","uz":"Har oy yangilang va öşa guruhda davom eting. Kabinetingiz tanlovingizdan yaratiladi."},"id":"s3","title":{"en":"Renewal","ru":"Продление","uz":"Yangilaş"}}],"subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Three steps","ru":"Три шага","uz":"Uç qadam"},"type":"steps"},{"enabled":true,"id":"hw-packages","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"Packages","ru":"Пакеты","uz":"Paketlar"},"type":"packages"},{"count":6,"enabled":true,"id":"hw-faq","subtitle":{"en":"","ru":"","uz":""},"title":{"en":"FAQ","ru":"FAQ","uz":"Savol-javob"},"type":"faq"}]}'::jsonb AND "data"->'faq' = '[{"a":{"en":"The monthly total is the sum of selected course prices. The package (Flex/Winx) only sets how many courses you take at once.","ru":"Месячная сумма — сумма цен выбранных курсов. Пакет (Flex/Winx) лишь определяет число одновременных курсов.","uz":"Oylik summa — tanlangan kurslar narxlarining yiğindisi. Paket (Flex/Winx) faqat bir vaqtdagi kurslar sonini belgilaydi."},"id":"f1","q":{"en":"How is the subscription price calculated?","ru":"Как рассчитывается цена абонемента?","uz":"Abonement narxi qanday hisoblanadi?"}},{"a":{"en":"No. Each course may appear once in a subscription; duplicates are blocked.","ru":"Нет. Каждый курс может быть в абонементе один раз; дубликаты блокируются.","uz":"Yöq. Har bir kurs abonementda bir marta bölişi mumkin; takroriy tanlov bloklanadi."},"id":"f2","q":{"en":"Can I select the same course twice?","ru":"Можно ли выбрать один курс дважды?","uz":"Bir kursni ikki marta tanlaş mumkinmi?"}},{"a":{"en":"The builder flags the conflict immediately and blocks activation. Choose another group.","ru":"Конструктор сразу показывает конфликт и не позволяет активировать. Выберите другую группу.","uz":"Abonement yiğuvçi töqnaşuvni darhol körsatadi va faollaştirişga ruxsat bermaydi. Boşqa guruhni tanlang."},"id":"f3","q":{"en":"What if schedules overlap?","ru":"Что если расписания пересекаются?","uz":"Jadval töqnaşsa nima böladi?"}},{"a":{"en":"Yes. When you renew, you continue in the same groups.","ru":"Да. При продлении вы продолжаете обучение в тех же группах.","uz":"Ha. Yangilaganda siz öşa guruhlarda öqişni davom ettirasiz."},"id":"f4","q":{"en":"Do I keep my group when I renew?","ru":"Сохраняется ли моя группа при продлении?","uz":"Yangilaganda guruhim saqlanib qoladimi?"}},{"a":{"en":"No. Visibility and enrollment are separate: a public page or video doesn’t grant a seat in a paid group.","ru":"Нет. Видимость и зачисление разделены: публичная страница или видео не даёт места в платной группе.","uz":"Yöq. Köriniş va röyxatdan ötiş alohida: ommaviy sahifa yoki video pullik guruhda örin bermaydi."},"id":"f5","q":{"en":"Does a public video give free course access?","ru":"Даёт ли публичное видео бесплатный доступ к курсу?","uz":"Ommaviy video kursga bepul kiriş beradimi?"}},{"a":{"en":"Only the teacher, authorized Super Admin, and the students or groups the teacher selected.","ru":"Только преподаватель, уполномоченный Супер-админ и выбранные преподавателем студенты или группы.","uz":"Faqat öqituvçi, vakolatli Super Admin va öqituvçi tanlagan talabalar yoki guruhlar."},"id":"f6","q":{"en":"Who sees private materials?","ru":"Кто видит приватные материалы?","uz":"Yopiq materiallarni kim köradi?"}}]'::jsonb AND "data"->'announcements' = '[{"audience":"all","body":{"en":"Seats in new Bazis and Frontend groups are limited.","ru":"Места в новых группах Bazis и Frontend ограничены.","uz":"Bazis va Frontend kurslarida yangi guruhlar uçun örinlar çeklangan."},"enabled":true,"id":"a1","title":{"en":"October groups are open","ru":"Открыты группы на октябрь","uz":"Oktyabr guruhlari oçildi"}},{"audience":"teachers","body":{"en":"Remember to select an audience for private materials.","ru":"Не забывайте выбирать аудиторию для приватных материалов.","uz":"Yopiq materiallar uçun auditoriya tanlaşni unutmang."},"enabled":true,"id":"a2","title":{"en":"For teachers: visibility settings","ru":"Для преподавателей: настройки видимости","uz":"Öqituvçilar uçun: köriniş sozlamalari"}}]'::jsonb;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n = 1 THEN applied := applied + 1; ELSE skipped := skipped + 1; RAISE NOTICE 'content sync: % skipped (not in the expected state)', 'site settings'; END IF;
  EXCEPTION WHEN OTHERS THEN
    failed := failed + 1;
    RAISE WARNING 'content sync: % failed: %', 'site settings: brand, nav, pages, faq, announcements', SQLERRM;
  END;

  -- package pkg-duo: Duo
  BEGIN
    INSERT INTO "AuditEvent" ("id", "tenantId", "action", "entityType", "entityId", "before", "after", "reason")
    SELECT 'content-sync-20261101-restore-Package-pkg-duo', t, 'content.sync.restore', 'Package', 'pkg-duo', jsonb_build_object('name', "name", 'description', "description", 'perks', "perks"), '{"description":{"en":"Two courses at the same time.","ru":"Два курса одновременно.","uz":"Ikki kursni bir vaqtda o‘qing."},"name":{"en":"Duo","ru":"Duo","uz":"Duo"},"perks":[{"en":"Two groups, two schedules","ru":"Две группы, два расписания","uz":"Ikki guruh, ikki jadval"},{"en":"Access to all teacher channels","ru":"Доступ ко всем каналам преподавателей","uz":"Barcha o‘qituvchi kanallariga kirish"},{"en":"Group materials","ru":"Материалы групп","uz":"Guruh materiallari"}]}'::jsonb, 'Approved local content transferred to production (2026-11-01)'
    FROM "Package" WHERE "id" = 'pkg-duo' AND "tenantId" = t AND "name" = '{"en":"Flex","ru":"Flex","uz":"Flex"}'::jsonb AND "description" = '{"en":"Two courses at the same time.","ru":"Два курса одновременно.","uz":"Ikki kursni bir vaqtda öqing."}'::jsonb AND "perks" = '[{"en":"Two groups, two schedules","ru":"Две группы, два расписания","uz":"Ikki guruh, ikki jadval"},{"en":"Access to all teacher channels","ru":"Доступ ко всем каналам преподавателей","uz":"Barça öqituvçi kanallariga kiriş"},{"en":"Group materials","ru":"Материалы групп","uz":"Guruh materiallari"}]'::jsonb
    ON CONFLICT ("id") DO NOTHING;
    UPDATE "Package" SET "name" = '{"en":"Duo","ru":"Duo","uz":"Duo"}'::jsonb, "description" = '{"en":"Two courses at the same time.","ru":"Два курса одновременно.","uz":"Ikki kursni bir vaqtda o‘qing."}'::jsonb, "perks" = '[{"en":"Two groups, two schedules","ru":"Две группы, два расписания","uz":"Ikki guruh, ikki jadval"},{"en":"Access to all teacher channels","ru":"Доступ ко всем каналам преподавателей","uz":"Barcha o‘qituvchi kanallariga kirish"},{"en":"Group materials","ru":"Материалы групп","uz":"Guruh materiallari"}]'::jsonb, "updatedAt" = now() WHERE "id" = 'pkg-duo' AND "tenantId" = t AND "name" = '{"en":"Flex","ru":"Flex","uz":"Flex"}'::jsonb AND "description" = '{"en":"Two courses at the same time.","ru":"Два курса одновременно.","uz":"Ikki kursni bir vaqtda öqing."}'::jsonb AND "perks" = '[{"en":"Two groups, two schedules","ru":"Две группы, два расписания","uz":"Ikki guruh, ikki jadval"},{"en":"Access to all teacher channels","ru":"Доступ ко всем каналам преподавателей","uz":"Barça öqituvçi kanallariga kiriş"},{"en":"Group materials","ru":"Материалы групп","uz":"Guruh materiallari"}]'::jsonb;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n = 1 THEN applied := applied + 1; ELSE skipped := skipped + 1; RAISE NOTICE 'content sync: % skipped (not in the expected state)', 'package pkg-duo'; END IF;
  EXCEPTION WHEN OTHERS THEN
    failed := failed + 1;
    RAISE WARNING 'content sync: % failed: %', 'package pkg-duo: Duo', SQLERRM;
  END;

