  -- Center ce-chilonzor
  BEGIN
    INSERT INTO "AuditEvent" ("id", "tenantId", "action", "entityType", "entityId", "before", "after", "reason")
    SELECT 'content-sync-20261101-restore-Center-ce-chilonzor', t, 'content.sync.restore', 'Center', 'ce-chilonzor', jsonb_build_object('description', "description", 'district', "district"), '{"description":{"en":"Sample lab for IT and programming.","ru":"Демо-лаборатория IT и программирования.","uz":"IT va dasturlash bo‘yicha namuna laboratoriya."},"district":{"en":"Chilanzar","ru":"Чиланзар","uz":"Chilonzor"}}'::jsonb, 'Approved local content transferred to production (2026-11-01)'
    FROM "Center" WHERE "id" = 'ce-chilonzor' AND "tenantId" = t AND "description" = '{"en":"Sample lab for IT and programming.","ru":"Демо-лаборатория IT и программирования.","uz":"IT va dasturlaş böyiça namuna laboratoriya."}'::jsonb AND "district" = '{"en":"Chilanzar","ru":"Чиланзар","uz":"Çilonzor"}'::jsonb
    ON CONFLICT ("id") DO NOTHING;
